#include "native_nand_banner.hpp"
#include <cassert>
#include <cstdio>
int main(){NANDBanner banner;const u16 title[]={'M',0x2605,0};const u16 empty[]={0};NANDInitBanner(&banner,0x12345678,title,empty);assert(banner.signature==0x5749424e&&banner.flag==0x12345678&&banner.comment[0][0]=='M'&&banner.comment[0][1]==0x2605&&banner.comment[1][0]==' ');NANDSetIconSpeed(&banner,0,NAND_BANNER_ICON_ANIM_SPEED_SLOW);banner.bannerTexture[0]=0x12;banner.iconTexture[0][0]=0x34;Native::encodeNandBanner(&banner);auto p=reinterpret_cast<const u8*>(&banner);const u8 expected[]={'W','I','B','N',0x12,0x34,0x56,0x78,0,3};assert(!std::memcmp(p,expected,10));assert(p[32]==0&&p[33]=='M'&&p[34]==0x26&&p[35]==5&&p[96]==0&&p[97]==' ');assert(banner.bannerTexture[0]==0x12&&banner.iconTexture[0][0]==0x34);u16 full[33];for(int i=0;i<33;++i)full[i]='A';NANDInitBanner(&banner,0,full,empty);for(int i=0;i<32;++i)assert(banner.comment[0][i]=='A');assert(banner.comment[1][0]==' ');std::puts("PASS Wii save banner: initialization, empty fallback, bounded UTF-16 copy, BE header/text and texture preservation");}
